"""File cache for TTS announcements generated by the configured HA engine."""

from __future__ import annotations

import asyncio
import hashlib
import json
import logging
import os
import re
import time
from collections import OrderedDict
from collections.abc import Callable, Iterable
from datetime import timedelta
from pathlib import Path
from typing import Any

from homeassistant.components import tts
from homeassistant.core import HomeAssistant
from homeassistant.util import dt as dt_util

from .const import (
    CONF_TTS_ENGINE,
    CONF_TTS_LANGUAGE,
    CONF_TTS_OPTIONS,
    CONF_TTS_PREWARM,
    DOMAIN,
    ENTRY_TYPE,
    ENTRY_TYPE_SETTINGS,
)
from .device import TtsFailed, tts_text

_LOGGER = logging.getLogger(__name__)

TTS_TIMEOUT = 15.0
PREWARM_CONCURRENCY = 2
PREWARM_QUEUE_SIZE = 500  # pending texts (both priorities)
PREWARM_PER_CALL = 30  # titles of one browse/favorites answer
PREWARM_BREAKER_FAILURES = 3
PREWARM_PAUSE = 300  # seconds
PREWARM_QUOTA_MAX_PAUSE = 86400  # seconds, cap of a parsed retry delay
PREWARM_RETRY_AFTER = 600  # seconds before a failed text is tried again
QUOTA_RE = re.compile(
    r"RESOURCE_EXHAUSTED|\b429\b.*(?:quota|rate)|(?:quota|rate).*\b429\b",
    re.IGNORECASE | re.DOTALL,
)
RETRY_DELAY_RE = re.compile(
    r"retryDelay['\"]?\s*:\s*['\"]?(\d+(?:\.\d+)?)s|retry in (\d+(?:\.\d+)?)",
    re.IGNORECASE,
)
CACHE_DIR = "kidshub_tts"
EXTENSIONS = ("mp3", "wav", "ogg", "flac")
NAME_RE = re.compile(r"^[0-9a-f]{64}\.(mp3|wav|ogg|flac)$")
CONTENT_TYPES = {
    "mp3": "audio/mpeg",
    "wav": "audio/wav",
    "ogg": "audio/ogg",
    "flac": "audio/flac",
}


class TtsCache:
    """Generate TTS audio once per text and keep it on disk."""

    def __init__(self, hass: HomeAssistant) -> None:
        self.hass = hass
        self.directory = Path(hass.config.path(CACHE_DIR))
        self._inflight: dict[str, asyncio.Task[str]] = {}
        # called with every engine error (the prewarmer pauses on quota errors)
        self.on_error: Callable[[BaseException], object] | None = None

    def _settings(self) -> tuple[str, str, dict[str, Any]]:
        for entry in self.hass.config_entries.async_entries(DOMAIN):
            if entry.data.get(ENTRY_TYPE) == ENTRY_TYPE_SETTINGS:
                engine = entry.options.get(CONF_TTS_ENGINE)
                if not engine:
                    break
                return (
                    engine,
                    entry.options.get(CONF_TTS_LANGUAGE) or "",
                    dict(entry.options.get(CONF_TTS_OPTIONS) or {}),
                )
        raise TtsFailed("no TTS engine configured")

    @property
    def prewarm_enabled(self) -> bool:
        """Return the ``tts_prewarm`` option of the settings entry (default on)."""
        for entry in self.hass.config_entries.async_entries(DOMAIN):
            if entry.data.get(ENTRY_TYPE) == ENTRY_TYPE_SETTINGS:
                return bool(entry.options.get(CONF_TTS_PREWARM, True))
        return True

    @staticmethod
    def cache_key(engine: str, language: str, options: dict[str, Any], text: str) -> str:
        """Return ``sha256(engine|language|options-json|text)`` (protocol 3.4)."""
        options_json = json.dumps(options, sort_keys=True, separators=(",", ":"))
        raw = "|".join([engine, language, options_json, text])
        return hashlib.sha256(raw.encode()).hexdigest()

    def _find(self, key: str) -> str | None:
        for ext in EXTENSIONS:
            if (self.directory / f"{key}.{ext}").is_file():
                return f"{key}.{ext}"
        return None

    def _store(self, key: str, ext: str, data: bytes) -> str:
        self.directory.mkdir(parents=True, exist_ok=True)
        name = f"{key}.{ext}"
        tmp = self.directory / f".{name}.tmp"
        tmp.write_bytes(data)
        os.replace(tmp, self.directory / name)
        return name

    async def _generate(
        self,
        key: str,
        text: str,
        engine: str,
        language: str,
        options: dict[str, Any],
        quiet: bool = False,
    ) -> str:
        try:
            async with asyncio.timeout(TTS_TIMEOUT):
                source_id = tts.generate_media_source_id(
                    self.hass, text, engine, language or None, options or None
                )
                ext, data = await tts.async_get_media_source_audio(
                    self.hass, source_id
                )
        except TimeoutError as err:
            raise TtsFailed("TTS engine timed out") from err
        except Exception as err:
            if self.on_error is not None:
                self.on_error(err)
            # prewarm failures are counted by the prewarm circuit breaker instead
            (_LOGGER.debug if quiet else _LOGGER.warning)(
                "TTS generation failed: %s", err
            )
            raise TtsFailed("TTS generation failed") from err
        if ext not in EXTENSIONS or not data:
            raise TtsFailed("TTS engine returned unusable audio")
        return await self.hass.async_add_executor_job(self._store, key, ext, data)

    async def _ensure(self, key: str, *args: Any) -> str:
        found = await self.hass.async_add_executor_job(self._find, key)
        return found or await self._generate(key, *args)

    @property
    def configured(self) -> bool:
        """Return whether a TTS engine is configured."""
        try:
            self._settings()
        except TtsFailed:
            return False
        return True

    def _task(
        self, text: str, *, join: bool = True, quiet: bool = False
    ) -> asyncio.Task[str] | None:
        """Return the generation task of ``text``, shared by all callers.

        With ``join=False`` an already running generation returns None instead.
        """
        engine, language, options = self._settings()
        key = self.cache_key(engine, language, options, text)
        task = self._inflight.get(key)
        if task is not None:
            return task if join else None
        task = self.hass.async_create_task(
            self._ensure(key, text, engine, language, options, quiet)
        )
        if not task.done():  # an eagerly started task may already be finished
            self._inflight[key] = task
        task.add_done_callback(lambda t: self._done(key, t))
        return task

    def _done(self, key: str, task: asyncio.Task[str]) -> None:
        if self._inflight.get(key) is task:
            del self._inflight[key]
        # a cancelled prewarm worker leaves the shielded task unawaited
        if not task.cancelled():
            task.exception()

    async def get_url(self, text: str) -> str:
        """Return the proxy URL of the audio for ``text`` (generating it once)."""
        task = self._task(text)
        assert task is not None
        name = await asyncio.shield(task)
        return f"/api/kidshub/tts/{name}"

    async def prewarm(self, text: str) -> None:
        """Generate the audio of ``text`` unless cached or already in flight."""
        task = self._task(text, join=False, quiet=True)
        if task is not None:
            await asyncio.shield(task)

    async def read(self, name: str) -> bytes | None:
        """Return the cached file ``name`` (already validated) or None."""
        path = self.directory / name

        def _read() -> bytes | None:
            try:
                return path.read_bytes()
            except OSError:
                return None

        return await self.hass.async_add_executor_job(_read)


class TtsPrewarmer:
    """Background queue that fills the TTS cache ahead of the first tap.

    Two priorities: high (root lists, favorites, room names) is served first and
    is never evicted by low (list children). The queue is bounded: a full queue
    drops the newest low-priority texts. At most ``PREWARM_CONCURRENCY``
    generations run at a time. After ``PREWARM_BREAKER_FAILURES`` consecutive
    failures prewarming pauses; failing texts are not retried for a while. It
    never raises.
    """

    def __init__(self, hass: HomeAssistant, cache: TtsCache) -> None:
        self.hass = hass
        self.cache = cache
        cache.on_error = self._on_quota
        self._clock = time.monotonic
        self._high: OrderedDict[str, None] = OrderedDict()
        self._low: OrderedDict[str, None] = OrderedDict()
        self._workers: set[asyncio.Task[None]] = set()
        self._failures = 0
        self._paused_until = 0.0
        self._paused_wall: Any = None  # wall-clock time of the pause end
        self._pause_reason: str | None = None
        self._failed: dict[str, float] = {}  # text -> retry not before

    @property
    def busy(self) -> bool:
        """Return whether texts are pending or being generated."""
        return bool(self._high or self._low or self._workers)

    def _paused(self) -> bool:
        return self._clock() < self._paused_until

    def status(self) -> dict[str, Any]:
        """Return the prewarm state for diagnostics."""
        paused = self._paused()
        return {
            "enabled": self.cache.prewarm_enabled,
            "paused_until": self._paused_wall.isoformat() if paused else None,
            "reason": self._pause_reason if paused else None,
            "queue": len(self._high) + len(self._low),
        }

    def _skip(self, text: str) -> bool:
        until = self._failed.get(text)
        if until is None:
            return False
        if self._clock() < until:
            return True
        del self._failed[text]
        return False

    def schedule(
        self,
        texts: Iterable[object],
        *,
        priority: bool = False,
        limit: int | None = None,
    ) -> None:
        """Queue ``texts`` (normalised like a ``tts`` request) for generation."""
        try:
            if (
                not self.cache.prewarm_enabled
                or self._paused()
                or not self.cache.configured
            ):
                return
            count = 0
            for text in texts:
                if limit is not None and count >= limit:
                    break
                say = tts_text(text)
                if say is None:
                    continue
                count += 1
                self._add(say, priority)
            while (
                (self._high or self._low)
                and len(self._workers) < PREWARM_CONCURRENCY
            ):
                task = self.hass.async_create_background_task(
                    self._work(), "kidshub tts prewarm"
                )
                self._workers.add(task)
                task.add_done_callback(self._workers.discard)
        except Exception as err:  # noqa: BLE001 - pre-warming is best effort
            _LOGGER.debug("TTS prewarm scheduling failed: %s", err)

    def _add(self, text: str, priority: bool) -> None:
        if text in self._high or self._skip(text):
            return
        if not priority:
            if text not in self._low and (
                len(self._high) + len(self._low) < PREWARM_QUEUE_SIZE
            ):
                self._low[text] = None
            return
        self._low.pop(text, None)
        if len(self._high) + len(self._low) >= PREWARM_QUEUE_SIZE:
            if not self._low:
                return  # full of high-priority texts
            self._low.popitem(last=True)  # evict the newest low-priority text
        self._high[text] = None

    def _next(self) -> str | None:
        for queue in (self._high, self._low):
            if queue:
                return queue.popitem(last=False)[0]
        return None

    async def _work(self) -> None:
        while not self._paused() and (text := self._next()) is not None:
            try:
                await self.cache.prewarm(text)
            except asyncio.CancelledError:
                raise
            except Exception as err:  # noqa: BLE001 - pre-warming is best effort
                _LOGGER.debug("TTS prewarm of %r failed: %s", text, err)
                if not self._on_quota(err):
                    self._on_failure(text)
            else:
                self._failures = 0

    @staticmethod
    def _error_text(err: BaseException) -> str:
        parts: list[str] = []
        seen: set[int] = set()
        while err is not None and id(err) not in seen:
            seen.add(id(err))
            parts.append(str(err))
            err = err.__cause__ or err.__context__  # type: ignore[assignment]
        return " | ".join(parts)

    def _on_quota(self, err: BaseException) -> bool:
        """Pause for the quota reset if ``err`` is a quota error; return whether."""
        message = self._error_text(err)
        if not QUOTA_RE.search(message):
            return False
        if self._paused():
            return True  # a parallel worker already paused and logged
        seconds: float | None = None
        if match := RETRY_DELAY_RE.search(message):
            seconds = min(float(match[1] or match[2]), PREWARM_QUOTA_MAX_PAUSE)
        if seconds is None or seconds <= 0:
            now = dt_util.now()
            midnight = (now + timedelta(days=1)).replace(
                hour=0, minute=0, second=0, microsecond=0
            )
            seconds = (midnight - now).total_seconds()
        self._paused_until = self._clock() + seconds
        self._paused_wall = dt_util.now() + timedelta(seconds=seconds)
        self._pause_reason = "quota"
        self._failures = 0
        self._high.clear()
        self._low.clear()
        _LOGGER.warning(
            "Gemini-/TTS-Kontingent erschöpft – Vorerzeugen pausiert bis %s",
            dt_util.as_local(self._paused_wall).strftime("%H:%M"),
        )
        return True

    def _on_failure(self, text: str) -> None:
        now = self._clock()
        self._failed[text] = now + PREWARM_RETRY_AFTER
        self._failures += 1
        if self._failures >= PREWARM_BREAKER_FAILURES and not self._paused():
            self._paused_until = now + PREWARM_PAUSE
            self._paused_wall = dt_util.now() + timedelta(seconds=PREWARM_PAUSE)
            self._pause_reason = "failures"
            self._failures = 0
            self._low.clear()
            _LOGGER.warning(
                "TTS prewarming paused for %d min after %d failures in a row",
                PREWARM_PAUSE // 60,
                PREWARM_BREAKER_FAILURES,
            )

    def cancel(self) -> None:
        """Drop pending texts and stop the workers (entry unload)."""
        self._high.clear()
        self._low.clear()
        for task in list(self._workers):
            task.cancel()
        self._workers.clear()
